// Given: draggable visuals for the dot product, the cross product and projection (pill 0.4).
// Do not edit this file. Same pattern as demo 0: a player you can step through, with two
// handles (the tips of a and b) you can drag; the real algorithm re-runs on every drag.
import { recordTrace, type Recording } from "../trace/trace";
import type { Vec2 } from "../math/vec2";
import { makeDraggable } from "./drag";
import { createPlayer } from "./player";
import { tracedCross, tracedDot, tracedProjection } from "./algos/vectorProducts";

function mount(container: HTMLElement, record: (a: Vec2, b: Vec2) => Recording): () => void {
  let a: Vec2 = { x: 3, y: 1 };
  let b: Vec2 = { x: 1, y: 2 };
  const rec = () => record(a, b);
  const player = createPlayer(container, rec(), { center: { x: 1.5, y: 1.2 }, pixelsPerMetre: 80 });
  const undrag = makeDraggable(
    player.view,
    [
      { get: () => a, set: (p) => (a = p) },
      { get: () => b, set: (p) => (b = p) },
    ],
    () => player.setRecording(rec()),
  );
  player.goTo(2); // start on the last step, where the result shows
  return () => {
    undrag();
    player.destroy();
  };
}

export const createDotVisual = (c: HTMLElement) =>
  mount(c, (a, b) => recordTrace(() => tracedDot(a, b)));
export const createCrossVisual = (c: HTMLElement) =>
  mount(c, (a, b) => recordTrace(() => tracedCross(a, b)));
export const createProjectionVisual = (c: HTMLElement) =>
  mount(c, (a, b) => recordTrace(() => tracedProjection(a, b)));
